package thaumcraft.api.book;
import java.util.*;
import thaumcraft.api.research.ResearchDefinition;
/** Shared validation before a reload snapshot can replace the last working catalog. */
public final class CatalogValidator {
 public static void validate(Map<String,ResearchDefinition> research,BookCatalog books){research=thaumcraft.api.research.ResearchLinks.resolve(research);books.validate(research);var done=new HashSet<String>();var active=new HashSet<String>();for(var d:research.values()){for(var parent:java.util.stream.Stream.concat(d.parents().stream(),d.hiddenParents().stream()).toList())if(!research.containsKey(parent))throw new IllegalArgumentException("Unknown parent "+parent);for(var sibling:d.siblings())if(!research.containsKey(sibling))throw new IllegalArgumentException("Unknown sibling "+sibling);for(var required:d.pageRequirements().values())if(!research.containsKey(required))throw new IllegalArgumentException("Unknown page requirement "+required);visit(d.key(),research,done,active);}for(var page:books.pages().values()){PageTypes.validate(page);for(var element:page.elements()){if(element.kind().equals("link")&&!research.containsKey(element.value()))throw new IllegalArgumentException("Unknown research link "+element.value());if(element.kind().equals("aspect")&&thaumcraft.api.aspects.Aspect.getAspect(element.value())==null)throw new IllegalArgumentException("Unknown aspect "+element.value());}}}
 private static void visit(String key,Map<String,ResearchDefinition> research,Set<String> done,Set<String> active){if(done.contains(key))return;if(!active.add(key))throw new IllegalArgumentException("Research cycle at "+key);var d=research.get(key);if(d==null)throw new IllegalArgumentException("Unknown research "+key);for(String parent:java.util.stream.Stream.concat(d.parents().stream(),d.hiddenParents().stream()).toList())visit(parent,research,done,active);if(!d.linkedResearch().isEmpty())visit(d.linkedResearch(),research,done,active);active.remove(key);done.add(key);}
 private CatalogValidator(){}
}
